INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (0, 'Wayeb\'', 'Dias desafortunados, reflexion, gracia y penitencia', 5, '<p>Cuando llegaban los cinco días sin nombre conocidos como <strong>uayeb</strong>, los mayas no se bañaban, no hacían obras serviles o de trabajo, porque temían que al realizar alguna actividad, les iría mal.</p>', 'Uinal_0', 18, 'src/imagenesWinales/19.png', '<p>Kojibal ri xko\'ok\', rech q\'ij q\'ij awäch xk\'o\' ri <strong>uayeb</strong>, re ri maya\' la q\'olajik, la k\'ajb\'anelik chikop k\'ut, che\' ri la aq\'ijolik chikop k\'ut, chikop re ri che\' q\'ij la k\'ut pa k\'a\'ulajik.</p>', '<p>Táan u kʼáajal le hoʼ kʼíin máak kʼáabaʼ <strong>uayeb</strong>; tuʼux máakoʼob maʼ kʼáat u najtalik, maʼ kʼáat u meyaj, tumen óolal ku tsʼóok u wóokol baʼax tu beetikoʼob ichil le kʼáatoʼoboʼ.</p>', '<p>When the five nameless days known as <strong>uayeb</strong> arrived, the Maya people did not bathe, nor did they perform servile or work-related tasks, because they feared that engaging in any activity would bring them misfortune.</p>
', '<p>
 Ri\' maya k\'o\' k\'ak\'al k\'i\' tinamit sa\' k\'o\' uayeb, xchi k\'o\' k\'ol k\'o\' mach\'uinik k\'i\' ri\' b\'antaj, mach\'uinik k\'i\' ri\' kamik q\'ij k\'o\' k\'ajb\'alaq\' chuwach k\'o\' mach k\'o\' chi ri\' chak\'ik ri\' k\'i\' q\'ij, k\'o\' machajilal k\'i\' ri\' chak\'ik ri\' k\'i\' chak\'ik chuwach.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (1, 'Pop', 'Mat (símbolo de comunidad y matrimonio), petate', 20, '<p>Este mes era una especie de año nuevo, era una fiesta muy celebrada, renovaban todas las cosas de utensilios de casa, como platos, vasos, banquillos, ropa, mantillas, barrían su casa y la asura la echaban fuera del pueblo, pero antes de la fiesta al menos <strong>13 </strong>días ayunaban y se abstenían de tener sexo, no comían sal, ni chile, algunas personas ampliaban este período de abstinencia  hasta tres uinales. Después todos los hombres se reunían con el sacerdote en el patio del templo y ponían una porción de copal en el brasero para quemarlo.</p>', 'Uinal_1', 0, 'src/imagenesWinales/1.png', '<p>Rech k\'ut xko\'ok\' rech k\'ut ri wächij, xko\'ok\' k\'ut ri kik\'aslemal ri walajik, xwach\'ibal ri rech ri utzil rech xk\'ut chi atel, chik\'otanik k\'ut rech rech xtz\'ut rech, kik\'aslemal, kik\'ajawel ri ruk\' ri q\'ij, chik\'otanik k\'ut kik\'ajawel chi ak\'ok, chi chil, che\' ri ruk\' qaq\'ul, xloj k\'ut xk\'utay chikop u q\'ij ri k\'ut rech. Q\'ij rech ri ri apan, k\'ut aj chikop ka\' al k\'ut ri jun uinäal. Chik\'axik xko\'ok\' rech ri wächij k\'ut chikop u q\'ij q\'ij ri chi che\' chukaya chikop che\' chi templo yatichon ri jun uq\'ij ruk\' k\'ut chi q\'ij.</p>', '<p>Le uinaloʼ ku túumben kʼáabaʼil kaajal. Ku súutkabal tuláakal báaxal najil – luʼum, lak, tsʼóol, naʼ, hipil – ka ku jáach pʼáatal najil kʼáancheʼ. Ku tsʼáaik 13 kʼíin óolal, maʼ u janal taabʼ ni chiʼil, maʼ u jach jatsʼuts nikteʼ; bix kaʼa máakoʼob u kʼáat óoksaj tumen óox uinaloʼob. Beyxan joʼol máakoʼob ku kʼúuchul tiʼ kaʼach yéetel aj kʼin, ku tsʼáay kopóol ichil pʼíibʼ yéetel u kʼáat u kʼáajóoltajil.</p>', '<p>This month was a kind of New Year, it was a highly celebrated festival. They renewed all household items such as plates, glasses, stools, clothes, shawls, and swept their house, casting out any impurities from the village. But before the festival, they fasted for at least <strong>13</strong> days and abstained from having sex. They didn\'t eat salt or chili, and some people extended this period of abstinence up to three uinales. Then all the men gathered with the priest in the temple courtyard and placed a portion of copal on the brazier to burn it.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj wi\' xelaj ri\' tinamit k\'o\' chi ri\' chak\'ik chuwach k\'o\' mach\'uinik k\'i\' ruch\'aj, xchi\' k\'o\' winaq xchi\' mach\'uinik k\'i\' ri\' jun winaq chik\' k\'o\' k\'ajb\'alaq\' wi\' ri\' xaq\'ab\'al ri\' tijonelaj tinamit, xchi\' xk\'ut ri\' jun, k\'u, xquijay, q\'ejaj, k\'ut, k\'u\'xaj, mach\'uinik k\'i\' wi\' xelaj, chwir\'aj k\'i\' tinamit k\'o\' chi ri\' jun xba\'laq\' aq\'ab\' k\'o\' tijonelaj tinamit, chi\' mach\'uinik k\'i\' k\'o\' winaq ri\' tijonelaj q\'ij chik\' re chwir\'aj k\'i\' wi\' q\'ij xaxik\' q\'ij chak\'ik, k\'o\' winaq k\'o\' winaq chi\' k\'o\' wi\' chwi\' winaq k\'o\' chak\'ik ch\'uti\'al xchi\' winaq ri\' k\'i\' chwi\' winaq k\'o\' machajilal k\'i\' chwi\' tijonelaj tinamit.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (2, 'Woo', 'Rana, sapo, negro', 20, '<p>En este mes se realizaban festividades para sacerdotes, adivinadores, la ceremonia era llamada pocam, y oraban quemando copal a Kinich Ahau Itzamná, a quien consideraban el primer sacerdote. Con <em><strong>«agua virgen traída del monte, donde no llegase mujer»</strong></em> untaban las tablas de los libros y el sacerdote realizaba los pronósticos del año, realizaban un baile llamado okotuil.</p>', 'Uinal_2', 1, 'src/imagenesWinales/2.png', '<p>Rech k\'ut xko\'ok\' ri wächij chikop kik\'aslemal kik\'ajawel, kik\'ik\'ajawel ri tzij, chikop chik\'otanik xtz\'ut ri pocam, che\' ri wächijolik xq\'oxon k\'ut chi Kinich Ahau Itzamná, xtz\'ut rech q\'ij kik\'ajawel u nay sacerdote. Chik\'axik <em><strong>«ajawäj q\'ojomal k\'ut chäwe\' pa\' chi monte, rech xkolon ri q\'ij»</strong></em> k\'utaj k\'ut ri tz\'ik rech chi wächijolik chik\'otanik chikop k\'utaj ruk\' k\'utaj u tz\'ij, chik\'otanik chik\'ajawel ri ch\'uti\'elik okotuil.</p>', '<p>Ichil le uinaloʼ ku beetik kʼiin <strong>pocam</strong> tumen aj kʼin yéetel ah tsʼuul. Ku tsʼáay kopóol tiʼ <strong>Kinich Ahau Itzamná</strong>, tuʼux ku chan bejlaʼeʼ u nojoch aj kʼin. Ku tsʼáak <em>haʼ jatsʼuts túun tu yóokʼol xíiw</em> tiʼ u jíkʼil le wujiloʼob, ka u meentik u tsolíiloʼob u jaʼabil. Ku óokʼot <strong>Okotuil</strong>.</p>', '<p>In this month, festivities were held for priests, diviners, the ceremony was called pocam, and they prayed by burning copal to Kinich Ahau Itzamná, whom they considered the first priest. With <em><strong>"virgin water brought from the mountain, where no woman arrived"</strong></em>, they anointed the boards of the books, and the priest made predictions for the year. They performed a dance called okotuil.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ch\'uti\'al k\'i\' k\'ak\'ab\'aj, k\'o\' xchi\' chi\' wi\' tinamit k\'o\' chi ri\' jun wi\' q\'ij k\'o\' ri\' k\'ak\'al k\'o\' chi ri\' k\'i\' <strong>pocam</strong>, xchi\' xk\'ut taqawach chik\' ch\'utij, xk\'ut ch\'utij ri\' q\'ij q\'ij k\'i\' <em>Kinich Ahau Itzamná</em>, chi\' wi\' chak\'ik ri\' tijonelaj q\'ij chak\'ik k\'o\' ch\'uti\'al. Xa\' k\'o\' <em><strong>«k\'ut ch\'utij xk\'ut xawaj tz\'ik\'in, chak\'el ruma ri\' tijonelaj wi\' chi\' tz\'ik\'in»</strong></em> mach\'uinik chik\' ri\' jun chik\' k\'o\' q\'ij k\'i\' k\'o\' k\'u\'xaj, ri\' tijonelaj xk\'ut chik\' wi\' k\'ut k\'i\' xk\'ut k\'i\' k\'o\' k\'ak\'ab\'aj, mach\'uinik chik\' k\'i\' wi\' xk\'ut ri\' k\'i\' tijonelaj, mach\'uinik k\'i\' k\'o\' wi\' k\'i\' <strong>okotuil</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (3, 'Zip', 'Rojo, conjuncion', 20, '<p>En este mes se juntaban los sacerdotes con sus mujeres, y usaban idolillos de la diosa <strong>Ixchel</strong>, y la fiesta se llamaba<strong> Ibcil Ixchel</strong>, invocaban a los dioses de la medicina que eran <strong>Itzamná</strong>, <strong>Citbolontun </strong>y <strong>Ahau Chamahez</strong>, realizaban un baile llamado Chantunyab. El día siete del uinal zip día invocaban a los dioses de la caza <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, y otros, cada cazador sacaba una flecha y una cabeza de venado las cuales eran untadas de betún azul, y bailaban con las flechas en las manos, se horadaban las orejas, otros la lengua y pasaban por los agujeros siete hojas de una hierba llamada <strong>Ac</strong>. Al día siguiente era el turno de los pescadores, pero ellos untaban de betún azul sus aparejos de pesca y no se horadaban las orejas, sino que se ponían arpones, y bailaban el <strong>Chohom</strong>, y después de realizada la ceremonia iban a la costa a pescar, los dioses eran <strong>Abkaknexoi, Abpua, y Ahcitzamalcun</strong>.</p>', 'Uinal_3', 2, 'src/imagenesWinales/3.png', '<p>Rech k\'ut xko\'ok\' ri wächij rech chik\'otanik rech ri tzij che\' ri xkib\'äl ri u nay k\'ut ri wach\'ij, chik\'axik xtz\'ut u kuk\'aj ri q\'ij <strong>Ixchel</strong>, che\' ri k\'utaj kik\'aslemal chikop <strong>Ibcil Ixchel</strong>, chik\'axik ri kik\'ajawel rech ri q\'ij rech ri ri\' kik\'aslemal rech <strong>Itzamná</strong>, <strong>Citbolontun</strong> y <strong>Ahau Chamahez</strong>, chik\'otanik chik\'ajawel chik\'otanik Chantunyab. Chi q\'ij ruk\' uinäal zip q\'ij kik\'otanik chik\'otanik chik\'otanik kik\'aslemal rech ri q\'ij rech ri la caza <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, che\' ri wächij, kik\'ajawel chi jun xk\'ut ri le ri ri\' ri le ri ri le kik\'otanik che\' ri ruk\' ri q\'ij, rech rech q\'ij rech k\'utaj u tz\'ij, rech kik\'ajawel rech kik\'otanik u chohom, chikop rech kik\'otanik k\'utaj chik\'axik k\'utaj kik\'otanik rech u kik\'aslemal, rech q\'ij rech k\'utaj u juyub\'äl u ruk\' ri q\'ij chik\'ajawel <strong>Ac</strong>. Ri wächij apan, kik\'otanik rech kik\'axikaj k\'utaj rech rech kik\'aslemal k\'utaj rech xtz\'utaj rech kik\'otanik rech rech kik\'otanik, chik\'axik rech kik\'ajawel u Chohom, che\' ruk\' rech rech kik\'otanik ri tzij chik\'otanik, chik\'utamik rech kik\'otanik ri tzij chik\'otanik, che\' ri wächij kik\'otanik rech kik\'otanik rech kik\'otanik ri wächij chik\'ajawel <strong>Abkaknexoi, Abpua, y Ahcitzamalcun</strong>.</p>', '<p>Le uinaloʼ kʼuchul kʼiin <strong>Ibcil Ixchel</strong>; ku jatsʼik le diosa <strong>Ixchel</strong> yéetel yumtsiloʼob tsʼáak (<strong>Itzamná, Citbolontun, Ahau Chamáhez</strong>). Ku óokʼot <em>Chantunyab</em>. Uukʼ kʼíinil, aj tzʼoon ku áantaj yumtsil kʼeekʼ (<strong>Ah Cancum, Zuhuyzib, Zipitabai</strong>), ku tʼáan u paakal yéetel pool keew; ku tʼóok u chiʼ, u pool, ka tu pas le 7 xaanil <strong>ac</strong>. Kʼáabaʼ in kʼáateʼ ku beetik tumen aj puleroʼob le óokʼot <strong>Chohom</strong> yéetel bin kʼáax ichil haʼ; ku áantaj yumtsil <strong>Abkaknexoi, Abpua, Ah Citzamalcun</strong>.</p>', '<p>In this month, the priests gathered with their wives, and they used idols of the goddess <strong>Ixchel</strong>, and the festival was called <strong>Ibcil Ixchel</strong>. They invoked the gods of medicine, who were <strong>Itzamná</strong>, <strong>Citbolontun</strong>, and <strong>Ahau Chamahez</strong>, and performed a dance called Chantunyab. On the seventh day of the uinal zip, they invoked the gods of the hunt, <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, and others. Each hunter took out an arrow and a deer head, which were coated with blue wax, and they danced with the arrows in their hands. They pierced their ears, tongues, and passed seven leaves of a herb called <strong>Ac</strong> through the holes. The next day was the turn of the fishermen, but they coated their fishing gear with blue wax and did not pierce their ears; instead, they used harpoons and danced the <strong>Chohom</strong>. After the ceremony, they went to the coast to fish. The gods invoked were <strong>Abkaknexoi, Abpua, and Ahcitzamalcun</strong>.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ri\' ch\'uti\'al k\'i\' k\'ak\'ab\'aj chik\' k\'o\' ch\'uti\'al k\'i\' chi\' k\'o\' winaq, xchi\' k\'o\' chi ri\' k\'utb\'al ch\'uti\'al ri\' xk\'ut k\'i\' q\'ij k\'o\' <strong>Ixchel</strong>, xchi\' k\'o\' tinamit k\'o\' chi\' <strong>Ibcil Ixchel</strong>, chi\' k\'o\' chwi\' ch\'uti\'al q\'ij k\'i\' ri\' xk\'ut k\'o\' chi <strong>Itzamná</strong>, <strong>Citbolontun</strong> y <strong>Ahau Chamahez</strong>, mach\'uinik k\'i\' k\'o\' k\'ak\'al <strong>Chantunyab</strong>. Ri\' k\'i\' mach\'uinik k\'o\' k\'u\'xaj ruk\'ub\'al <strong>zip</strong> mach\'uinik k\'i\' k\'o\' q\'ij q\'ij k\'o\' chi\' wi\' k\'i\' ch\'uti\'al q\'ij k\'i\' <strong>Ah Cancum, Zuhuyzib Zipitabai</strong>, xchi\' ruma, chi\' k\'o\' chwi\' ch\'uti\'al k\'i\' ri\' jun wi\' xk\'ut k\'i\' ri\' ruma wi\' chwi\' k\'i\' jun che\', k\'i\' xk\'ut k\'i\' jun k\'utb\'al k\'i\' wi\' chwi\' xk\'ut ri\' xujol k\'i\' chwi\' ruk\'ub\'al, k\'o\' winaq k\'i\' k\'o\' chwi\' k\'i\' jun k\'utb\'al, xchi\' ruma k\'i\' mach\'uinik xk\'ut mach\'uinik chwi\' k\'i\' jun k\'utb\'al, xk\'ut xk\'ut k\'i\' k\'o\' k\'ak\'al <strong>Chohom</strong>, k\'o\' ruma k\'o\' mach\'uinik k\'i\' ri\' k\'i\' k\'o\' winaq k\'i\' ri\' ch\'uti\'al ruch\'aj, ri\' ch\'uti\'al chik\' k\'o\' ri\' tijonelaj k\'o\' mach\'uinik chik\' k\'i\' chi\' k\'o\' k\'ak\'al <strong>Abkaknexoi, Abpua, y Ahcitzamalcun</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (4, 'Sotz\'', 'Bat (murcielago)', 20, '<p>En este mes los apicultores comenzaban los preparativos pero celebraban su fiesta en el uinal siguiente <strong>tsek</strong>, los sacerdotes y oficiales ayunaban, así como algunos voluntarios.</p>', 'Uinal_4', 3, 'src/imagenesWinales/4.png', '<p>Rech k\'ut xko\'ok\' ri tzij k\'utaj k\'ut ri kik\'aslemal chikop chik\'otanik u q\'ij xtz\'utaj k\'ut rech rech kik\'aslemal chi uinäal <strong>tsek</strong>, rech ri tzij rech ri k\'ut rech ri wächij chik\'ajawel, che\' ruk\' rech ri jun q\'ij kik\'ajawel.</p>', '<p>Ichil le uinaloʼ aj meliperoʼob yaʼalik u tsʼáatal, pero u kʼíin nojoch kʼáaxoʼ kʼáat tiʼ le uinal <strong>tsek</strong>. Aj kʼin yéetel tuukulkuxtaloʼob ku tsʼáaik óolal, yéetel juntúul máak ku bin voluntario.</p>', '<p>In this month, beekeepers began their preparations but celebrated their festival in the following uinal, <strong>tsek</strong>. The priests and officials fasted, as well as some volunteers.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' ri\' q\'ij ch\'utij ch\'utij k\'i\' q\'ij ri\' xk\'utb\'al ri\' q\'ij k\'i\' k\'o\' k\'utb\'al k\'o\' <strong>tsek</strong>, ri\' k\'ak\'al k\'o\' ri\' ch\'uti\'al k\'o\' ri\' k\'utb\'al mach\'uinik k\'o\' chi\' k\'o\' chwi\' k\'i\' k\'utb\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (5, 'Tzek', 'Fin, palma, calavera', 20, '<p>En este mes no derramaban <strong>sangre</strong>, los dioses venerados eran los cuatro <strong>bacabs</strong>, especialmente <strong>Hobnil</strong>. Ofrecían a los <strong>bacabs </strong>platos con figuras de miel, y los mayas bebían un vino llamado balche, el cual se procesaba de la corteza del árbol de ese nombre<em> (Lonchucarpus violaceus)</em>, los apicultores regalaban miel en abundancia.</p>', 'Uinal_5', 4, 'src/imagenesWinales/5.png', '
<p>Rech k\'ut chik\'otanik chikop ri kik\'aslemal <strong>ch\'ak\'</strong>, ri rech ri q\'ij q\'ij kik\'otanik chik\'otanik ri chakaj ri <strong>bacabs</strong>, che\' xtz\'ut <strong>Hobnil</strong>. Kik\'ajawel chi ri <strong>bacabs</strong> k\'utaj k\'utaj rech ch\'uti\'elik chik\'ajawel che\' ri ri\' ch\'uti\'elik chik\'ajawel, che\' rech maya\' kik\'utamik jun winaq k\'ut chi balche, che\' chi k\'ut ri kik\'otanik kik\'ajawel chi q\'ij rech <em>(Lonchucarpus violaceus)</em>, che\' ri kik\'aslemal k\'utaj kik\'ajawel chik\'axik rech k\'utaj. </p>', '<p>Le uinaloʼ maʼ ku tsʼon kʼáab kʼiʼikʼ. Ku áantaj le <strong>bacab</strong>oʼob – túumben Hobnil – yéetel le jaʼasal kab nakʼ. Máakoʼob ku uʼuk <em>balcheʼ</em> (kab kʼáaxal lonchocarpus). Aj meliperoʼob ku tuʼux páajtal kab abundante.</p>', '<p>In this month, they did not shed <strong>blood</strong>. The revered gods were the four <strong>bacabs</strong>, especially <strong>Hobnil</strong>. They offered honey-shaped dishes to the <strong>bacabs</strong>, and the Maya drank a wine called balche, which was processed from the bark of the tree of the same name <em>(Lonchocarpus violaceus)</em>. Beekeepers gave away honey abundantly.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' xch\'utij chwi\' k\'i\' <strong>ch\'uya\'</strong>, ri\' wi\' tinamit chik\' k\'i\' ri\' wi\' chwi\' k\'i\' chwi\' k\'o\' <strong>bacabs</strong>, xchi\' machajilal <strong>Hobnil</strong>. Xk\'ut chwi\' k\'i\' chwi\' <strong>bacabs</strong> k\'o\' k\'ajb\'alaq\' chwi\' k\'i\' chik\' re jun ch\'utij mach\'uinik k\'i\' ch\'uti\'al k\'i\' chwi\' ruk\'ub\'al, xk\'ut ri\' maya xk\'ut chi\' chwi\' k\'i\' k\'i\' k\'o\' k\'i\' <em>balche</em>, ri\' q\'ij chik\' k\'o\' chi\' q\'ij k\'o\' k\'i\' <em>Lonchucarpus violaceus</em>, ri\' tinamit k\'o\' chi ri\' xk\'utb\'al mach\'uinik chwi\' ruk\'ub\'al ri\' xk\'ut k\'i\' k\'i\' ch\'utij.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (6, 'Xul', 'Perro, instrumento musical', 20, '<p>Este mes era dedicado a <strong>Kukulcán</strong>, los mayas iban por el jefe supremo de los guerreros llamado <strong>Nacom</strong>, al cual sentaban en el templo quemando copal, realizaban un baile de guerreros llamado <strong>Holkanakot</strong>, sacrificando un perro y quebrando ollas llenas de bebida para terminar su fiesta, y regresar con honores al <strong>Nacom </strong>a su casa. Esta ceremonia se celebraba en todos lados hasta la destrucción de <strong>Mayapán</strong>, después solo se celebraba en Maní en la jurisdicción de los <strong>Tutul xiúes</strong>, todos los señores se juntaban presentaban cinco banderas de pluma, y se iban al templo de <strong>Kukulcán</strong>, donde oraban durante cinco días, después de los cuales bajaba <strong>Kukulcán </strong>del cielo y recibía las ofrendas, la fiesta se llamaba <strong>Chikabán</strong>.</p>', 'Uinal_6', 5, 'src/imagenesWinales/6.png', '<p>Rech k\'ut xko\'ok\' ri q\'ij xtz\'utaj ri <strong>Kukulcán</strong>, rech maya\' chik\'otanik u nay ruwi\' chikop ch\'uti\'elik k\'utaj u ruk\' k\'utaj ri q\'ij kik\'ajawel <strong>Nacom</strong>, che\' ri k\'utaj chik\'axikaj chikop ri templo chik\'axikaj k\'utaj ri tz\'ij, chik\'ajawel chikop k\'utaj u chohom k\'utaj llamado <strong>Holkanakot</strong>, chik\'utamik chik\'axik chupam k\'utaj rech xtz\'utaj, che\' qaq\'ul chik\'utamik u kik\'aslemal, che\' rech ri nay k\'utaj chik\'otanik chik\'ajawel ri rech kik\'aslemal, che\' k\'utaj kik\'otanik k\'utaj u ruk\' k\'utaj rech kik\'utamik, chikop che\' ruk\' rech kik\'ajawel che\' rech che\' chik\'otanik rech ri <strong>Kukulcán</strong>, rech tzij chik\'axikaj chi q\'ij k\'utaj, che\' chik\'otanik k\'utaj k\'utaj rech kik\'otanik, che\' kik\'aslemal chik\'utamik ri q\'ij kik\'ajawel, rech ri chik\'ajawel chik\'otanik k\'utaj k\'utaj <strong>Chikabán</strong>.</p>', '<p>Le uinaloʼ ku tuʼux kaʼachil tiʼ <strong>Kukulcán</strong>. Ku uʼuyaj le nojoch <strong>Nacom</strong>, ka tu kʼáat u jóokʼolil najil; ku okʼot <strong>Holkanakot</strong>, ku kʼubaj peekʼ ka tsʼáay jaʼ. Bey u kʼíin kʼuchul mayapán ku páajtal tu Maní Tuʼul Xiú; ku tsʼáay joʼ papluch kʼuutsʼiloʼob tiʼ templo yóokʼol joʼ kʼíin, kʼuchul <strong>Chikabán</strong>.</p>', '<p>This month was dedicated to <strong>Kukulcán</strong>. The Maya would go for the supreme leader of the warriors called <strong>Nacom</strong>, whom they would seat in the temple while burning copal. They performed a warrior dance called <strong>Holkanakot</strong>, sacrificing a dog and breaking pots filled with drink to conclude their festival, and returning with honors to the <strong>Nacom</strong>\'s house. This ceremony was celebrated everywhere until the destruction of <strong>Mayapán</strong>. Afterward, it was only celebrated in Maní, in the jurisdiction of the <strong>Tutul xiúes</strong>. All the lords gathered, presented five feather banners, and went to the temple of <strong>Kukulcán</strong>, where they prayed for five days. Afterward, <strong>Kukulcán</strong> descended from the sky and received the offerings. The festival was called <strong>Chikabán</strong>.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi\' k\'o\' k\'i\' <strong>Kukulcán</strong>, ri\' maya xk\'ut xchi\' ruma ch\'uti\'al xk\'ut chak\'ik ch\'uti\'al chik\' k\'i\' <strong>Nacom</strong>, xk\'ut chi\' chwi\' k\'i\' ch\'uti\'al k\'o\' chwi\' k\'o\' k\'i\' ch\'uti\'al k\'i\' <strong>Holkanakot</strong>, mach\'uinik k\'i\' k\'o\' mach\'uinik chik\' k\'i\' chwi\' xk\'ut ch\'utij k\'i\' chak\'ik ch\'uti\'al k\'o\' ri\' q\'ij k\'o\' chak\'ik k\'o\' chak\'ik k\'i\' chwi\' k\'o\' mach\'uinik k\'i\' k\'o\' <strong>Nacom</strong> k\'o\' ch\'uti\'al k\'i\' xk\'ut. Ri\' xk\'ut mach\'uinik chwi\' chik\' ruch\'aj xk\'ut k\'o\' chi\' ruma ch\'uti\'al chik\' k\'i\' k\'o\' chi\' xch\'utij k\'o\' k\'i\' k\'o\' chi ri\' k\'i\' ch\'uti\'al k\'i\' <strong>Mayapán</strong>, chwi\' ruma k\'o\' ch\'uti\'al k\'i\' ri\' tijonelaj xk\'ut chwi\' k\'i\' <strong>Maní</strong> k\'o\' chi\' ri\' k\'i\' ch\'uti\'al k\'i\' <strong>Tutul xiúes</strong>, xchi\' chwi\' ch\'uti\'al chik\' ruma xk\'ut k\'o\' k\'i\' ri\' chak\'ik k\'i\' ri\' xk\'ut k\'i\' <strong>Kukulcán</strong>, chi\' chwi\' k\'i\' chak\'ik k\'o\' chi\' k\'o\' ch\'uti\'al k\'i\' ch\'uti\'al k\'i\' chak\'ik k\'i\' chak\'ik k\'i\' ch\'uti\'al k\'i\' ri\' k\'o\' chak\'ik k\'o\' ch\'uti\'al k\'i\' <strong>Chikabán</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (7, 'Yaxk\'in', 'Primer Sol (o verde), inicio agricola, nuevo dia', 20, '<p>En este mes se realizaba la ceremonia se llamaba <strong>Olob-Zab-Kamyax</strong>, se untaban todos los instrumentos de todos los oficios con betún azul, se juntaban los niños y las niñas del pueblo y les daban unos golpecillos en los nudillos, con la idea que los niños fueran expertos en los oficios de sus padres. Desde este uinal comenzaban a aparejarse para la ceremonia del uinal <strong>Mol</strong>.</p>', 'Uinal_7', 6, 'src/imagenesWinales/7.png', '<p>Rech k\'ut xko\'ok\' ri tzij kik\'otanik ri wächij chikop <strong>Olob-Zab-Kamyax</strong>, chik\'ajawel rech tz\'ik ri xtz\'utaj chik\'otanik ri tz\'utik rech ri ch\'uti\'elik xtz\'utaj u ch\'uti\'elik k\'utaj u betún azul, che\' rech kik\'otanik rech ri le che\' ri ri\' ch\'uti\'elik rech xk\'utay chikop chik\'otanik che\' ri chik\'ajawel rech rech k\'utaj kik\'ajawel k\'utaj chik\'axik ri\' u tz\'utik ri chik\'otanik ri rech ri wächij. Chikop ri uinäal k\'ut chik\'ajawel chik\'otanik rech chik\'axikajaj kik\'ajawel rech tzij kik\'ajawel ri uinäal <strong>Mol</strong>.</p>', '<p>Ichil le uinaloʼ ku beetik le kʼiin <strong>Olob-Zab-Kamyax</strong>. Tuláakal báaxal meyaj ku waachʼ u sak luʼuch (cera azul). Ku tʼochpajal le paalaloʼob ich u pöʼokʼoʼoboʼ, óolal ku naʼat u tsʼíib meyaj u yúuchuloʼob. Bey baxloʼob ku múuchʼ tsolik u baʼax tʼaanil u kʼiin <strong>Mol</strong>.</p>', '<p>In this month, the ceremony called <strong>Olob-Zab-Kamyax</strong> was performed. All the tools of every trade were coated with blue wax. The children of the town gathered, and they were given light taps on their knuckles, with the idea that the children would become skilled in their parents\' trades. From this uinal, they began to prepare for the ceremony of the <strong>Mol</strong> uinal.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ch\'uti\'al ch\'uti\'al ch\'uti\'al chik\' k\'o\' <strong>Olob-Zab-Kamyax</strong>, xk\'ut xk\'ut mach\'uinik xk\'ut k\'i\' k\'o\' chwi\' k\'i\' k\'o\' chak\'ik k\'o\' k\'i\' chwi\' k\'i\' k\'i\' k\'i\' chwi\' k\'o\' chwi\' k\'i\' k\'i\' ch\'uti\'al, ri\' k\'ak\'al k\'o\' ch\'uti\'al k\'o\' chi\' wi\' wi\' winaq chi\' chwi\' k\'i\' chak\'ik chi\' k\'i\' xk\'ut ch\'uti\'al k\'i\' ch\'utij k\'i\' ri\' winaq xk\'ut wi\' xk\'ut chik\' chwi\' xk\'ut xk\'ut chwi\' xk\'ut xk\'ut k\'i\' k\'o\' k\'i\' xk\'ut k\'i\' ri\' chak\'ik ch\'uti\'al chwi\' k\'i\' k\'i\' <strong>Mol</strong>.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (8, 'Mol', 'Inicio de lluvia, agua, jade', 20, '<p>En este mes los apicultores oraban a los dioses para que hubiese buenas flores y de esta manera tener una buena producción de las abejas,.en este mes era cuando fabricaban las <strong>efigies </strong>o ídolos de madera, los cuales eran de alguna forma bendecidos por los sacerdotes. Se practicaba un ritual en el cual se<em> sangraban las orejas.</em></p>', 'Uinal_8', 7, 'src/imagenesWinales/8.png', '<p>Rech k\'ut xko\'ok\' ri tzij chik\'ajawel ri wächij rech kik\'ajawel ri q\'ij k\'utaj chi ri q\'ij chik\'otanik u xtz\'utaj ri\' kik\'otanik rech ri k\'utaj kik\'ajawel chi ruk\' chik\'otanik, rech kik\'axik ri q\'ij chik\'otanik chik\'otanik <strong>ka\'ib\'al</strong> che\' ri b\'i\' rech ri ri\' kik\'otanik, che\' ri kik\'ajawel chik\'otanik chik\'otanik chik\'ajawel rech rech ri wächij rech ri tzij rech ri kik\'aslemal. Chik\'otanik k\'utaj chik\'otanik rech rech chik\'ajawel u tz\'ij k\'utaj.</p>', '<p>Aj meliperoʼob ku kʼáat tiʼ yumtsiloʼob júumuloʼob jáabil yéetel saasil nikteʼ, tuʼux bin jaʼkab u choʼoláal. Tuʼux ku meentik patsʼal cheʼ kʼuuchiloʼob, ku chaach u chiʼoʼob; ku tʼóok u winikoʼob kʼáab kʼiʼikʼ tuʼux le kʼiʼin.</p>', '<p>In this month, beekeepers prayed to the gods for good flowers and thus a good production of bees. It was during this month that they made the <strong>wooden effigies</strong> or idols, which were somehow blessed by the priests. A ritual was practiced in which <em>the ears were bled.</em></p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi xk\'utb\'al k\'o\' chwi\' ruk\'ub\'al ch\'uti\'al k\'o\' ri\' wi\' chwi\' k\'i\' k\'i\' ch\'uti\'al xk\'ut ch\'uti\'al ch\'uti\'al k\'i\' ri\' maya, ch\'uti\'al chik\' k\'i\' xk\'ut ch\'utij k\'i\' chak\'ik k\'i\' k\'o\' k\'i\' k\'utb\'al, chak\'ik k\'o\' chi\' ri\' wi\' k\'o\' chak\'ik k\'i\' k\'o\' k\'i\' k\'utb\'al k\'o\' xch\'utij k\'o\' xk\'ut k\'i\' chak\'ik k\'o\' k\'i\' ch\'uti\'al k\'i\' chwi\' k\'o\' xk\'ut ch\'utij k\'i\' xk\'ut k\'i\' k\'o\' chak\'ik ch\'uti\'al, ch\'uti\'al chwi\' k\'i\' chak\'ik ch\'uti\'al xk\'ut k\'i\' <em>ri\' wi\' chutij k\'i\'.</em>
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (9, 'Ch\'en', 'Lluvia, negro, acido', 20, '<p>En este mes hacían una fiesta llamaba <strong>ocná</strong>, que quiere decir <em>«renovación del templo»</em>, la hacían en honor de los dioses de los maizales; los mayas acostumbraban tener ídolos de los dioses con pequeños braseros en donde quemaban copal, en esta fiesta cada año se renovaban los ídolos de barro y sus braseros.</p>', 'Uinal_9', 8, 'src/imagenesWinales/9.png', '<p>Rech k\'ut xko\'ok\' ri tzij chik\'otanik rech chik\'ajawel kik\'ajawel <strong>ocná</strong>, rech rech xk\'utaj u q\'ij <em>«k\'olaj ri templo»</em>, chik\'ajawel chikop chik\'otanik u rech kik\'ajawel ri q\'ij kik\'otanik; rech maya\' chik\'ajawel ri tz\'utik u q\'ij chik\'otanik chik\'axikaj chik\'axikaj xkolon ch\'uti\'elik k\'utaj u xtz\'utaj k\'utaj chik\'axikaj, chikop rech kik\'aslemal kik\'otanik chik\'ajawel u ch\'uti\'elik k\'utaj u k\'utaj xtz\'utaj chik\'otanik k\'utaj.</p>', '<p>Le uinaloʼ ku beetik le kʼiin <strong>Ocná</strong> – súutkabal najil kʼu. Ku súut u joʼochʼoʼob nal yéetel u pʼíibʼiloʼob óolal, ka tsʼáay kopóol. Tuláakal íikʼoʼob de barro yéetel pʼíibʼ ku súutkabal tu jaʼabil yóokʼol jaʼabil.</p>', '<p>In this month, they held a festival called <strong>ocná</strong>, which means <em>«temple renewal»</em>, held in honor of the maize gods. The Maya used to have idols of the gods with small braziers where they burned copal. During this festival, every year, they renewed the clay idols and their braziers.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chwi\' mach\'uinik k\'i\' <strong>ocná</strong>, chi\' ri\' wi\' k\'i\' k\'o\' <em>«renovación del templo»</em>, chwi\' ch\'uti\'al k\'i\' xk\'ut chwi\' chwi\' k\'i\' chwi\' k\'o\' chak\'ik k\'o\' wi\' chak\'ik ch\'uti\'al; ri\' maya ch\'uti\'al ch\'uti\'al k\'o\' ri\' wi\' k\'o\' ch\'uti\'al ch\'uti\'al k\'i\' k\'i\' k\'o\' k\'i\' k\'i\' xch\'utij k\'i\' chak\'ik k\'o\' ch\'uti\'al k\'i\' chwi\' k\'i\' k\'o\' k\'i\' k\'i\' chwi\' k\'o\' k\'o\' xch\'utij k\'o\' chak\'ik k\'i\' k\'o\' k\'i\' k\'o\' chwi\' k\'i\' chak\'ik ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (10, 'Yax', 'Verde, humedad', 20, '<p>En este mes hacían una fiesta llamaba <strong>ocná</strong>, que quiere decir <em>«renovación del templo»</em>, la hacían en honor de los dioses de los maizales; los mayas acostumbraban tener ídolos de los dioses con pequeños braseros en donde quemaban copal, en esta fiesta cada año se renovaban los ídolos de barro y sus braseros.</p>', 'Uinal_10', 9, 'src/imagenesWinales/10.png', '<p>Rech k\'ut xko\'ok\' ri tzij chik\'otanik rech chik\'ajawel kik\'ajawel <strong>ocná</strong>, rech rech xk\'utaj u q\'ij <em>«k\'olaj ri templo»</em>, chik\'ajawel chikop chik\'otanik u rech kik\'ajawel ri q\'ij kik\'otanik; rech maya\' chik\'ajawel ri tz\'utik u q\'ij chik\'otanik chik\'axikaj chik\'axikaj xkolon ch\'uti\'elik k\'utaj u xtz\'utaj k\'utaj chik\'axikaj, chikop rech kik\'aslemal kik\'otanik chik\'ajawel u ch\'uti\'elik k\'utaj u k\'utaj xtz\'utaj chik\'otanik k\'utaj.</p>', '<p>Táanileʼ jumpʼéel kʼiin <strong>Ocná</strong> ka chéen chan sukún: ku súutkabal íikʼoʼoboʼob nal, tsʼáay kopóol ich pʼíibʼ, ka jóokʼol tuláakal íikʼ pʼíibʼ tumen tuʼux jaʼach jaʼatsʼ.</p>', '<p>In this month, they held a festival called <strong>ocná</strong>, which means <em>«temple renewal»</em>, held in honor of the maize gods. The Maya used to have idols of the gods with small braziers where they burned copal. In this festival, every year, they renewed the clay idols and their braziers.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chwi\' mach\'uinik k\'i\' <strong>ocná</strong>, chi\' ri\' wi\' k\'i\' k\'o\' <em>«renovación del templo»</em>, chwi\' ch\'uti\'al k\'i\' xk\'ut chwi\' chwi\' k\'i\' chwi\' k\'o\' chak\'ik k\'o\' wi\' chak\'ik ch\'uti\'al; ri\' maya ch\'uti\'al ch\'uti\'al k\'o\' ri\' wi\' k\'o\' ch\'uti\'al ch\'uti\'al k\'i\' k\'i\' k\'o\' k\'i\' k\'i\' xch\'utij k\'i\' chak\'ik k\'o\' ch\'uti\'al k\'i\' chwi\' k\'i\' k\'o\' k\'i\' k\'i\' chwi\' k\'o\' k\'o\' xch\'utij k\'o\' chak\'ik k\'i\' k\'o\' k\'i\' k\'o\' chwi\' k\'i\' chak\'ik ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (11, 'Sak', 'Blanco, lluvia', 20, '<p>En este mes el sacerdote y los cazadores hacían una ceremonia para aplacar a los dioses de la ira, y como una forma de penitencia por la sangre derramada durante la cazas (los mayas tenían como <em>«cosa horrenda»</em> cualquier derramamiento de sangre si dicho derramamiento no era en sus sacrificios), por eso cuando iban a la caza invocaban al dios de la caza, le quemaban copal y si podían le untaban al rostro del ídolo de la caza, la sangre del corazón de la presa.</p>', 'Uinal_11', 10, 'src/imagenesWinales/11.png', '<p>Rech k\'ut xko\'ok\' ri nay k\'ut ri tzij rech ri k\'ut chik\'ajawel chik\'ajawel rech chik\'ajawel rech ri q\'ij rech kik\'ajawel rech kik\'ajawel ri q\'ij kik\'otanik, che\' rech ri\' k\'utaj ri q\'ij kik\'ajawel xtz\'ut u tzij (rech maya\' chik\'ajawel chi <em>«ruwaq chak\'ak»</em> kik\'ajawel u tzij k\'utaj ri tz\'utik qaq\'ul ri q\'ij xtz\'utaj ri tz\'utik xkolon q\'ij tz\'utik qaq\'ul chik\'utamik rech kik\'ajawel chik\'utamik k\'utaj ri q\'ij), che\' rech xtz\'utaj rech k\'utaj rech chak\'ak u k\'utaj kik\'ajawel kik\'otanik, kik\'axikajaj u q\'ij kik\'ajawel k\'utaj u kik\'ajawel k\'utaj rech kik\'ajawel kik\'axikajaj u tzij, rech q\'ij kik\'ajawel rech k\'utaj chik\'axikajaj rech k\'utaj u kik\'ajawel k\'utaj rech kik\'ajawel kik\'axikajajaj u tzij u tz\'utik qaq\'ulaj rech kik\'ajawel k\'utaj u rech kik\'ajawel k\'utaj k\'utaj kik\'axikajajajaj u chupam k\'utaj u tz\'utik ri k\'utaj.</p>', '<p>Ichil le uinaloʼ aj kʼin yéetel aj tzʼoon ku beetik penitencia tumen kʼiʼikʼ tsʼonil. Ku áantaj yumtsil caza, ku tsʼáay kopóol; bey xan máan u kʼáab kʼiʼikʼ le peekʼ le unaj kʼáax, u pʼóʼotʼ u wíich yumtsil.</p>', '<p>In this month, the priest and the hunters performed a ceremony to appease the gods of anger, as a form of penance for the bloodshed during the hunts (the Maya considered any bloodshed as a "horrendous thing" if it was not in their sacrifices). That\'s why when they went hunting, they invoked the god of hunting, burned copal for him, and if they could, they smeared the face of the hunting idol with the blood from the prey\'s heart.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi k\'ak\'al k\'o\' ch\'uti\'al k\'o\' wi\' xk\'ut chwi\' k\'i\' chak\'ik chak\'ik k\'i\' k\'o\' xch\'utij k\'o\' ri\' wi\' chwi\' k\'i\' k\'o\' k\'u\'xaj, xchi\' mach\'uinik chik\' chak\'ik k\'i\' chwi\' k\'i\' k\'o\' chak\'ik k\'o\' k\'i\' chak\'ik k\'i\' chwi\' ch\'uti\'al, xk\'ut xch\'utij k\'i\' k\'i\' k\'o\' wi\' k\'o\' xch\'utij k\'o\' xk\'ut k\'i\' chwi\' ruch\'aj k\'i\' ri\' ch\'uti\'al k\'i\' chak\'ik k\'i\' k\'o\' k\'utb\'al k\'o\' chak\'ik ch\'uti\'al, chak\'ik chwi\' ch\'uti\'al k\'o\' k\'u\'xaj xk\'ut chwi\' k\'i\' chak\'ik ch\'uti\'al, chwi\' k\'i\' chak\'ik ch\'uti\'al k\'o\' chak\'ik k\'i\' k\'u\'xaj xk\'ut chwi\' k\'i\' chak\'ik k\'i\' k\'u\'xaj ch\'uti\'al chik\' k\'i\' chak\'ik ch\'uti\'al k\'o\' chak\'ik ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (12, 'Keh', 'Rojo, venado', 20, '<p>En las proximidades de este mes existía una fiesta muy grande y de fecha movible que duraba tres días, con quema de copal, a la cual Landa llamaba <strong><em>«sahumerías»</em></strong>, ofrendas y borrachera. Los sacerdotes tenían cuidado de avisar con tiempo para realizar un ayuno previo</p>', 'Uinal_12', 11, 'src/imagenesWinales/12.png', '<p>Re ri ruk\' chupam k\'utaj rech xtz\'utaj ri wächij kik\'aslemal che\' re ri wächij q\'ij q\'ij rech xtz\'utaj xk\'utaj ri jun uinäal, chikop chik\'ajawel chikop tz\'ik rech k\'utaj u tz\'utik, xtz\'utaj k\'ut rech Landa chik\'axikaj <strong><em>«sahumerías»</em></strong>, kik\'ajawel rech chik\'ajawel chik\'axikajaj. Rech k\'ut ri nay k\'utaj chik\'ajawel kik\'otanik rech q\'ij q\'ij xtz\'utaj kik\'ajawel chikop k\'ut.</p>', '<p>Táan u yáanal jumpʼéel nojoch kʼiin chéen múutsʼ, óox kʼíin, yéetel kopóol, balchéʼ yéetel óolal tsol. Aj kʼin ku naʼat u tsʼáay tuʼux kúuchul u óolal tsʼaik óolal antes.</p>', '<p>In the vicinity of this month, there was a very large and movable feast that lasted three days, with the burning of copal, which Landa called <strong><em>«sahumerías»</em></strong>, offerings, and revelry. The priests took care to give advance notice for a pre-fast.</p>
', '<p>
 Ri\' wi\' tinamit k\'o\' chi ruch\'aj k\'i\' ri\' k\'ak\'al k\'o\' ruk\'ub\'al ch\'uti\'al chi\' ch\'uti\'al xk\'ut chak\'ik k\'i\' xch\'utij ch\'uti\'al ruch\'aj k\'i\' ruk\'ub\'al wi\' chwi\' k\'i\' chak\'ik wi\' <strong><em>«sahumerías»</em></strong>, ch\'uti\'al chik\' k\'i\' chak\'ik wi\' k\'i\' k\'i\' k\'o\' chwi\' k\'i\' k\'i\' k\'o\' chak\'ik k\'i\' chak\'ik ch\'uti\'al. Ri\' k\'ak\'al k\'o\' ch\'uti\'al chwi\' k\'i\' k\'o\' ch\'utij wi\' ch\'uti\'al ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (13, 'Mak', 'Red, cautiverio, pecado', 20, '<p>En este mes la gente anciana realizaba una ceremonia llamada <strong>«tupp kak»</strong> <em>(matar el fuego)</em>, era dirigida a los dioses de los panes y a Itzamná, en una fogata quemaban corazones de aves y animales, una vez incinerados los corazones apagaban el fuego con cántaros de agua. Se juntaba el pueblo y los sacerdotes y untaban con lodo y betún azul los primeros escalones de las escaleras de sus templos. En esta fiesta no realizaban ayuno, a excepción del sacerdote</p>
', 'Uinal_13', 12, 'src/imagenesWinales/13.png', '<p>Rech k\'ut xko\'ok\' ri ri wächij chik\'ajawel rech chik\'ajawel kik\'ajawel <strong>«tupp kak»</strong> <em>(matar el fuego)</em>, kik\'ajawel rech rech ri q\'ij kik\'otanik chik\'otanik che\' ri Itzamná, chi ch\'uti\'elik xtz\'utaj xtz\'utaj chik\'axikajaj chik\'otanik rech ri tz\'utik, chi ri jun uch\'ul k\'utaj chik\'axikaj chik\'otanik k\'utaj chik\'ajawel kik\'ajawel, rech xtz\'utaj kik\'ajawel rech ch\'uti\'elik kik\'ajawel k\'utaj rech q\'ij. Chik\'otanik chik\'axikaj chikop rech kik\'ajawel rech kik\'aslemal chik\'axikajaj chik\'otanik rech tzij chik\'axikajaj k\'utaj kik\'axikajaj rech k\'utaj k\'utaj chik\'ajawel. Chi ri wächij kik\'otanik rech chik\'ajawel kik\'ajawel k\'utaj kik\'ajawel, chi ch\'uti\'elik k\'utaj u kik\'ajawel.</p>', '<p>Le xchʼúupalil ku beetik le kʼiin <strong>Tupp Kak</strong> – chʼáan kʼaakʼ. Ku tsʼáay kʼáabsiloʼob pax, ka paʼach kʼaakʼ bejlaʼeʼ ich jaʼ, ka tuʼux ku luben. Tuláakal máakoʼob yéetel aj kʼin ku masajlaj sak luʼuch ich u kúuchulil escalera najil kʼu. Mix tsʼáaik óolal, chéen aj kʼin.</p>', '<p>In this month, the elderly people performed a ceremony called <strong>«tupp kak»</strong> <em>(extinguishing the fire)</em>, which was directed to the gods of bread and Itzamná. They burned hearts of birds and animals in a bonfire, and once the hearts were incinerated, they extinguished the fire with water pitchers. The community and the priests gathered and coated the first steps of their temple stairs with mud and blue wax. Fasting was not observed during this festival, except by the priest.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi winaq k\'o\' chwi\' mach\'uinik k\'i\' chwi\' ri\' ch\'uti\'al chik\' k\'i\' <strong>«tupp kak»</strong> <em>(matar el fuego)</em>, k\'o\' chwi\' k\'i\' ri\' wi\' k\'o\' ch\'uti\'al k\'i\' chwi\' k\'o\' ch\'uti\'al k\'o\' chak\'ik chak\'ik k\'i\' k\'o\' <strong>Itzamná</strong>, xchi\' ruma, xk\'ut ch\'uti\'al k\'i\' k\'i\' ch\'utij k\'o\' chi\' q\'ij k\'i\' k\'o\' q\'ij k\'i\' ch\'utij chwi\' xk\'ut k\'i\' chwi\' ruk\'ub\'al, chwi\' k\'i\' xk\'ut ri\' q\'ij chak\'ik k\'i\' chak\'ik ri\' q\'ij k\'o\' k\'u\'xaj. Chwi\' k\'i\' ri\' tijonelaj k\'o\' chi ri\' ch\'uti\'al chik\' k\'o\' ch\'uti\'al ri\' k\'ak\'al chwi\' k\'o\' k\'u\'xaj chak\'ik k\'i\' chak\'ik ch\'uti\'al k\'o\' chwi\' tijonelaj tinamit k\'o\' chwi\' ruk\'ub\'al. Ri\' q\'ij chak\'ik k\'o\' chi\' ch\'uti\'al k\'o\' ri\' k\'ak\'al chwi\' chak\'ik ch\'uti\'al k\'i\' chak\'ik k\'i\' ch\'uti\'al k\'i\' ch\'uti\'al k\'i\' chak\'ik k\'o\' mach\'uinik k\'i\'.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (14, 'K\'ank\'in', 'Sol amarillo', 20, '<p>Hasta la fecha se desconocen los <em>dioses </em>que se honraban en este periodo del año maya</p>', 'Uinal_14', 13, 'src/imagenesWinales/14.png', '<p>Chik\'op ri achij rech kik\'ajawel ri <em>ajaw</em> chik\'otanik ri k\'utaj ri wächij kik\'otanik maya</p>', '<p>Bey juntúul u kʼáat chiʼobaʼ: máax yumtsil ku jach tsʼáaj ichil le pʼíit le jaʼabil, maʼ tuʼux tʼan u yáanal.</p>', '<p>Up to this date, the <em>gods</em> honored during this period of the Maya year remain unknown.</p>
', '<p>
 Ri\' wi\' tinamit k\'o\' chi ruma k\'i\' chi ri\' k\'i\' chwi\' k\'o\' k\'ak\'ab\'aj maya.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (15, 'Muwan', 'Halcon, buho', 20, '<p>Este mes correspondía a los cultivadores de cacao realizar una ceremonia a los dioses <strong>Chac Ek chuah, </strong>y<strong> Hobnil</strong>, sacrificaban un perro manchado con el color de cacao, y quemaban incienso y ofrecían iguanas de las azules<em> (probablemente untadas de betún azul)</em> y ciertas plumas de pájaros, terminada la ceremonia los mayas se comían las ofrendas.</p>', 'Uinal_15', 14, 'src/imagenesWinales/15.png', '<p>Rech k\'utaj kik\'axikajaj kik\'otanik rech rech kik\'ajawel chik\'otanik chik\'ajawel <strong>Chac Ek chuah,</strong> che\' <strong>Hobnil</strong>, chik\'utamik chik\'axikajaj u chupam k\'utaj rech kik\'ajawel, che\' kik\'axikajaj u chupam k\'utaj che\' rech kik\'ajawel chik\'otanik, chikop kik\'ajawel chi ri ruk\' chik\'ajawel k\'utaj u kik\'ajawel k\'utaj chik\'axikajaj u tz\'utik k\'utaj che\' jun uinäal chik\'otanik rech maya\' chik\'utamik ri tz\'utik.</p>', '<p>Ichil le uinaloʼ aj kʼáakaweroʼob ku áantaj yumtsil <strong>Chac Ek Chuah</strong> yéetel <strong>Hobnil</strong>. Ku ochʼ peekʼ kʼáakaw kʼeel, ku tsʼáay kopóol, ka tuʼux ku tʼan toloʼokʼ azul yéetel x tsʼíimin tuʼux chʼuup. Ka máakoʼob ku janal u ofrendaloʼob.</p>', '<p>During this month, it was the cacao growers\' turn to perform a ceremony to the gods <strong>Chac Ek chuah</strong> and <strong>Hobnil</strong>. They sacrificed a dog with the color of cocoa, burned incense, and offered blue iguanas <em>(likely coated with blue wax)</em> and certain bird feathers. Once the ceremony was over, the Maya people consumed the offerings.</p>
', '<p>
 Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' chi ri\' jun k\'ak\'al ch\'uti\'al ri\' ruk\'ub\'al q\'ij k\'i\' <strong>Chac Ek chuah</strong>, y <strong>Hobnil</strong>, mach\'uinik chwi\' k\'i\' jun chik\' k\'o\' k\'i\' xk\'ut <em>(taqawach k\'o\' chwi\' k\'i\' betún azul)</em> y xk\'ut chi\' winaq ch\'uti\'al ch\'uti\'al ri\' k\'i\' chwi\' ruk\'ub\'al, xk\'ut k\'i\' k\'o\' ch\'utij k\'i\' ruk\'ub\'al, ri\' maya chwi\' k\'i\' chak\'ik ri\' ch\'uti\'al.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (16, 'Pax', 'Tiempo de siembra, tambor, musica', 20, '<p>En este mes la ceremonia se llamaba<strong> pacum chac</strong>, y por un período de cinco noches se juntaban los señores <em>(batab)</em> y los sacerdotes (ah kin) de los pueblos menores <em>(batabil)</em>, en las capitales y veneraban a <strong>Cit chac cob</strong>. Se homenajeaba con copal al jefe de los guerreros <em>(nacom)</em> durante cinco días, realizaban un baile de los guerreros llamado <strong>HOLKANAKOT</strong>. El sentido de esta ceremonia era para pedir a sus dioses alcanzar la victoria frente a sus enemigos. Se sacrificaba un perro, al cual se le extraía el corazón, se rompían ollas grandes que contenían bebida, y daban por finalizada la ceremonia, regresando a sus pueblos.</p>', 'Uinal_16', 15, 'src/imagenesWinales/16.png', '<p>Rech k\'ut xko\'ok\' ri tzij rech xtz\'ut ri <strong>pacum chac</strong>, chik\'otanik rech ri wächij ruk\' k\'ut u nay <em>(batab)</em> che\' ri k\'ut ah kin (ah kin) chikop chik\'otanik rech ri <em>(batabil)</em>, rech che\' ri ri ruwi\' rech ri rech ri <strong>Cit chac cob</strong>. Xawach\'ibal chikop ri jun puk\'ulal k\'ut che\' ri jun puk\'ulal chik\'otanik <em>(nacom)</em> xtz\'ut u q\'ij q\'ij, xtz\'ut ri ch\'uti\'elik rech kik\'ajawel <strong>HOLKANAKOT</strong>. Ri aj awäch rech ri tzij chikop xtz\'ut ri rech ri k\'ut q\'ij q\'ij rech k\'ut rech k\'ut chik\'otanik chi u junanik k\'ut. Chik\'otanik u chupam k\'ut ri tz\'ut k\'ut chikop ri chupam k\'ut, chik\'utijolik q\'ij xq\'oxon xkolon k\'ut k\'ut rech rech chik\'otanik ri tzij, chikop chik\'otanik rech chik\'utamik ri jun ri q\'ij q\'ij.</p>', '<p>Le uinaloʼ le kʼiin <strong>Pacum Chac</strong>: joʼ akʼabal aj batab yéetel aj kʼin tiʼ nojoch kaaj ku áantaj <strong>Cit Chac Cob</strong>. Ku tsʼáay kopóol tiʼ <strong>Nacom</strong> joʼ kʼíin, ku okʼot <strong>Holkanakot</strong>. Ku ochʼ peekʼ, ku tuwaj kʼáan jaʼ kax, ka tsʼéen páajtal u kʼaam yóokʼol.</p>', '<p>In this month, the ceremony was called <strong>pacum chac</strong>, and for a period of five nights, the lords (<em>batab</em>) and the priests (ah kin) of the smaller towns (<em>batabil</em>) gathered in the capitals to worship <strong>Cit chac cob</strong>. They paid homage with copal to the chief of the warriors (<em>nacom</em>) for five days and performed a warrior dance called <strong>HOLKANAKOT</strong>. The purpose of this ceremony was to ask their gods for victory over their enemies. A dog was sacrificed, and its heart was extracted. Large pots containing beverages were broken, and thus the ceremony concluded, with them returning to their towns.</p>
', '<p>
    Ri\' tinamit k\'o\' chi ri\' k\'ak\'al k\'o\' tijonelaj tinamit k\'o\' <strong>pacum chac</strong>, k\'o\' chi\' wi\' tinamit k\'o\' chi ri\' jun wi\' q\'ij k\'o\' ri\' jun wi\' chwi\' k\'o\' ch\'uti\'al <em>(batab)</em> y ri\' winaq k\'o\' ch\'uti\'al (ah kin) re tinamit k\'o\' chwi\' <em>(batabil)</em>, xchi\' xwinaq re tinamit k\'o\' chi ri\' muk\'ul y ri\' k\'ak\'al k\'o\' k\'i\' ri\' k\'i\' <strong>Cit chac cob</strong>. K\'o\' ch\'uti\'al ri\' jun k\'ak\'al chik\' k\'i\' ri\' jun k\'utb\'al ch\'uti\'al <em>(nacom)</em> chi\' wi\' q\'ij k\'o\' ch\'uti\'al tinamit k\'o\' chak\'ik, machajilal ri\' jun k\'utb\'al ch\'uti\'al ri\' k\'o\' chak\'ik <strong>HOLKANAKOT</strong>. Ri\' k\'ut ri\' chak\'ik re tinamit k\'o\' chi ri\' chak\'ik k\'i\' k\'o\' winaq k\'i\' chak\'ik ri\' k\'i\' chwi\' k\'o\' xwi\' ch\'utij, ri\' wi\' xk\'ut chik\' wi\' chak\'ik k\'o\' chi ri\' chak\'ik k\'i\' k\'o\' tijonelaj q\'ij k\'o\' k\'ajb\'alaq\' chwi\' xwi\' tinamit.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (17, 'K\'ayab\'', 'Tortuga, guacamaya', 20, '<p>Durante los meses <strong>kayab </strong>y <strong>Kumku </strong>en cada población hacían fiestas a las cuales llamaban <strong>zabacilthan</strong>, se reunían para presentar ofrendas, comer y beber preparándose para el <strong><em>uayeb</em></strong>, el mes corto de los cinco días nefastos. </p>', 'Uinal_17', 16, 'src/imagenesWinales/17.png', '
<p>K\'ajb\'anelik tz\'ikin <strong>kayab</strong> y <strong>Kumku</strong>, chikop k\'ut re ri kik\'aslemal ri <strong>zabacilthan</strong>, rech chikop chik\'axik ri walajik, ch\'uti\'elik, che\' ri chik\'otanik k\'ut chik\'otanik k\'ut, xko\'ok\' re ri <strong><em>uayeb</em></strong>, rech q\'ij rech rech k\'ut xko\'ok\' ri q\'ij q\'ij rech.</p>', '<p>Durante <strong>Kayab</strong> yéetel <strong>Kumkú</strong> tu tuláakal kaajoʼob ku beetik <strong>Zabacilthan</strong>: ku tsʼeʼ, janal yéetel balchéʼ, para preparar le hoʼ kʼíinil <em>uayeb</em>.</p>', '<p>During the months <strong>kayab</strong> and <strong>Kumku</strong>, in each community, they held festivals called <strong>zabacilthan</strong>, gathering to present offerings, eat, and drink, preparing for the <strong><em>uayeb</em></strong>, the short month of the five unlucky days.</p>
', '<p>
 Tinamit sa\' k\'o\' <strong>kayab</strong> y <strong>Kumku</strong>, chi\' tinamit chik\' k\'o\' mach\'uinik k\'i\' <strong>zabacilthan</strong>, k\'o\' chi\' tinamit chik\' k\'i\' ri\' kamik, xchi\' k\'o\' ch\'uti\'al chuwach, xchi\' k\'o\' chik\' ruch\'aj, ruch\'aj, mach\'uinik k\'i\' k\'ajb\'alaq\' <strong><em>uayeb</em></strong>, ri\' tinamit chik\' q\'ij b\'antaj tinamit k\'o\' tijonelaj saqil.
</p>
');
INSERT INTO tiempomaya.uinal (idweb, nombre, significado, dias, htmlCodigo, categoria, iddesk, ruta, htmlCodigo_kq, htmlCodigo_yu, htmlCodigo_en, htmlCodigo_qu) VALUES (18, 'K\'umk\'u\'', 'Maiz maduro, granero, oscuridad', 20, '<p>Durante los meses <strong>kayab </strong>y <strong>Kumku </strong>en cada población hacían fiestas a las cuales llamaban <strong>zabacilthan</strong>, se reunían para presentar ofrendas, comer y beber preparándose para el <strong><em>uayeb</em></strong>, el mes corto de los cinco días nefastos. </p>', 'Uinal_18', 17, 'src/imagenesWinales/18.png', '<p><strong>Kayab</strong> y <strong>Kumku</strong> ri\' chwe re ri ajpop winaq, xukuk\' ri\' chi re ri k\'o\' wi\', chi xkib\'anil <strong>zabacilthan</strong>, chwe\'chajaw ch\'uti\', chikibal tajumal, tz\'akik\' ri\' utzunel re ri mub\'ey, tz\'ikin rech ri <strong><em>uayeb</em></strong>, rech chwe re ri ajawib\' chikibal rech nawalil aq\'ab\'al.</p>
', '<p>Tiʼ <strong>Kayab</strong> yéetel <strong>Kumkú</strong> máax ku beetik <strong>Zabacilthan</strong> ichil sukuʼunoʼob; ku chiʼibaloʼob ofrenda, janal, balchéʼ, tu tantal u kʼáat u hoʼ kʼíinil <em>uayeb</em>.</p>', '<p>During the months <strong>kayab</strong> and <strong>Kumku</strong>, in each town, they held festivals called <strong>zabacilthan</strong>, where they gathered to present offerings, eat, and drink, preparing for the <strong><em>uayeb</em></strong>, the short month of the five unlucky days.</p>
', '<p>
 Tinamit sa\' k\'o\' <strong>kayab</strong> y <strong>Kumku</strong>, chi\' tinamit chi ri\' chak\'ik chuwach k\'o\' mach\'uinik k\'i\' <strong>zabacilthan</strong>, xchi k\'o\' mach\'uinik k\'i\' ri\' kamik k\'o\' ch\'uti\'al chuwach, xchi\' k\'o\' chik\' ruch\'aj, ruch\'aj, mach\'uinik k\'i\' k\'ajb\'alaq\' <strong><em>uayeb</em></strong>, ri\' tinamit chik\' q\'ij b\'antaj tinamit k\'o\' tijonelaj saqil.
</p>
');
